begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,brief_id uuid,revision_id uuid,package_id uuid,edited_id uuid,content jsonb,payload jsonb);
insert into fixture select gen_random_uuid(),id,gen_random_uuid(),gen_random_uuid(),null,gen_random_uuid(),'{"contractVersion":"forgestudio.social.v1","conceptSummary":"A factual campaign","variants":[{"variantKey":"primary","sequenceIndex":0,"platform":"facebook","caption":"Welcome to the community.","hashtags":[],"assetIds":[],"mediaUrls":[],"contentFormat":"text","linkUrl":"https://example.invalid/community"}],"claims":[]}',null from public.profiles where org_id='22222222-2222-2222-2222-222222222222' and role='admin' limit 1;
insert into public.properties(id,org_id,name)select property_id,'22222222-2222-2222-2222-222222222222','ForgeStudio editorial rollback fixture' from fixture;
do $$declare f fixture;r jsonb;input jsonb:='{"title":"Operator brief","objective":"Explain the community","channels":["facebook"],"formatPlan":[{"platform":"facebook","contentFormat":"text","quantity":1}],"sourceFacts":[{"text":"Private reviewed source","source":"operator"}]}';begin
 select * into f from fixture;
 perform pg_temp.check(public.save_forgestudio_brief(f.brief_id,f.property_id,gen_random_uuid(),input)->>'state'='forbidden','brief requires current property access');
 r:=public.save_forgestudio_brief(f.brief_id,f.property_id,f.actor_id,input);
 perform pg_temp.check(r->>'state'='saved' and r->'brief'->>'id'=f.brief_id::text,'brief and decision saved together');
 perform pg_temp.check(public.save_forgestudio_brief(f.brief_id,f.property_id,f.actor_id,input)->>'state'='replayed','lost brief reply recovers same saved brief');
 perform pg_temp.check(public.save_forgestudio_brief(f.brief_id,f.property_id,f.actor_id,input||'{"title":"Changed"}')->>'state'='request_conflict','request cannot change brief values');
 perform pg_temp.check(public.save_forgestudio_brief(gen_random_uuid(),f.property_id,f.actor_id,input||jsonb_build_object('assetIds',jsonb_build_array(gen_random_uuid())))->>'state'='asset_unavailable','foreign or missing assets cannot enter a brief');
 perform pg_temp.check(public.save_forgestudio_brief(gen_random_uuid(),f.property_id,f.actor_id,input||jsonb_build_object('connectionIds',jsonb_build_array(gen_random_uuid())))->>'state'='connection_unavailable','foreign or missing accounts cannot enter a brief');
 perform pg_temp.check((select count(*)=1 from public.social_content_briefs where property_id=f.property_id),'invalid/replayed requests do not leave extra briefs');
 perform pg_temp.check(not has_table_privilege('authenticated','public.forgestudio_commands','select') and not has_function_privilege('authenticated','public.save_forgestudio_brief(uuid,uuid,uuid,jsonb)','execute'),'browser cannot read private decisions or bypass attributed transaction');
 input:=jsonb_build_object('content',f.content,'authorKind','llm','briefId',f.brief_id,'validation','[[]]'::jsonb);
 update fixture set payload=input;
 r:=public.save_forgestudio_revision(f.revision_id,f.property_id,f.actor_id,input);
 perform pg_temp.check(r->>'state'='saved','package and initial revision save atomically');
 update fixture set package_id=(r->>'packageId')::uuid;
 perform pg_temp.check((select count(*)=1 and bool_and(link_url='https://example.invalid/community') from public.social_content_variants where revision_id=f.revision_id),'channel payload preserves reviewed link');
 perform pg_temp.check((select status='generated' from public.social_content_briefs where id=f.brief_id),'brief completion commits with package');
 perform pg_temp.check(public.save_forgestudio_revision(f.revision_id,f.property_id,f.actor_id,input)->>'state'='replayed','lost package save recovers original package and revision');
 perform pg_temp.check((select count(*)=1 from public.social_content_packages where property_id=f.property_id),'package replay cannot duplicate draft');
 perform pg_temp.check((select authored_by_kind='llm' and authored_by is null from public.social_content_revisions where id=f.revision_id),'machine-authored content does not impersonate operator');
end$$;
do $$declare f fixture;r jsonb;input jsonb;hash text;decision uuid:=gen_random_uuid();begin
 select * into f from fixture;select content_hash into hash from public.social_content_revisions where id=f.revision_id;
 input:=jsonb_build_object('revisionId',f.revision_id,'contentHash',hash,'decision','approved','note','Exact reviewed content');
 perform pg_temp.check(public.review_forgestudio_revision(decision,f.property_id,f.actor_id,input||'{"contentHash":"wrong"}')->>'state'='stale_revision','approval requires exact content hash');
 r:=public.review_forgestudio_revision(decision,f.property_id,f.actor_id,input);
 perform pg_temp.check(r->'revision'->>'approval_status'='approved','review and governance commit together');
 perform pg_temp.check(public.review_forgestudio_revision(decision,f.property_id,f.actor_id,input)->>'state'='replayed','lost approval reply recovers original decision');
 perform pg_temp.check(public.review_forgestudio_revision(gen_random_uuid(),f.property_id,f.actor_id,input||'{"decision":"denied"}')->>'state'='stale_revision','another reviewer cannot overwrite completed decision');
 perform pg_temp.check((select count(*)=1 from public.shared_approvals where property_id=f.property_id),'one approval governance record after replay');
 begin update public.social_content_revisions set content='{}' where id=f.revision_id;raise exception 'FAIL changed revision';exception when raise_exception then if SQLERRM<>'Create a new revision to edit saved content' then raise;end if;end;
 begin update public.social_content_variants set caption='Rewritten after approval' where revision_id=f.revision_id;raise exception 'FAIL changed variant';exception when others then if SQLERRM<>'Action history is immutable' then raise;end if;end;
 perform pg_temp.check((select content_hash=hash and approval_status='approved' from public.social_content_revisions where id=f.revision_id),'approved content and variants remain immutable');
 input:=jsonb_build_object('packageId',f.package_id,'expectedRevisionId',gen_random_uuid(),'content',f.content,'authorKind','user','reason','Improve explanation','validation','[[]]'::jsonb);
 perform pg_temp.check(public.save_forgestudio_revision(f.edited_id,f.property_id,f.actor_id,input)->>'state'='stale_revision','edit from old loaded version is rejected');
 update fixture set payload=input||jsonb_build_object('expectedRevisionId',f.revision_id);
end$$;
create function pg_temp.fail_editorial_history() returns trigger language plpgsql as $$begin if new.action='studio.revision.saved' then raise exception 'Fixture editorial history failure';end if;return new;end$$;
create trigger editorial_fixture_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_editorial_history();
do $$declare f fixture;begin
 select * into f from fixture;
 begin perform public.save_forgestudio_revision(f.edited_id,f.property_id,f.actor_id,f.payload);raise exception 'FAIL missing rollback';exception when raise_exception then if SQLERRM<>'Fixture editorial history failure' then raise;end if;end;
 perform pg_temp.check((select current_revision_id=f.revision_id and status='approved' from public.social_content_packages where id=f.package_id),'failed history rolls back package pointer and status');
 perform pg_temp.check((select approval_status='approved' from public.social_content_revisions where id=f.revision_id),'failed edit preserves previous approval');
 perform pg_temp.check(not exists(select 1 from public.social_content_revisions where id=f.edited_id) and not exists(select 1 from public.forgestudio_commands where id=f.edited_id),'failed edit leaves no orphan revision or command');
 perform pg_temp.check((select count(*)=1 from public.shared_approvals where property_id=f.property_id),'failed edit rolls back intermediate governance records');
end$$;
drop trigger editorial_fixture_failure on public.shared_action_events;
do $$declare f fixture;r jsonb;hash text;begin
 select * into f from fixture;
 r:=public.save_forgestudio_revision(f.edited_id,f.property_id,f.actor_id,f.payload);
 perform pg_temp.check(r->>'state'='saved' and r->'revision'->>'revision_number'='2','saved edit creates one pending revision');
 perform pg_temp.check((select approval_status='superseded' from public.social_content_revisions where id=f.revision_id),'successful edit supersedes original approval');
 perform pg_temp.check(public.save_forgestudio_revision(f.edited_id,f.property_id,f.actor_id,f.payload)->>'state'='replayed','lost edited revision reply is recoverable');
 select content_hash into hash from public.social_content_revisions where id=f.edited_id;
 r:=public.review_forgestudio_revision(gen_random_uuid(),f.property_id,f.actor_id,jsonb_build_object('revisionId',f.edited_id,'contentHash',hash,'decision','approved','note','Reviewed changed copy'));
 perform pg_temp.check(r->>'state'='saved','edited revision can be approved without colliding with its modification governance');
 perform pg_temp.check((select count(*)=3 from public.shared_approvals where property_id=f.property_id),'original review, modification and new review have distinct receipts');
 perform pg_temp.check((select count(*)=5 and bool_and(not training_eligible) and bool_and(request::text not like '%Private reviewed%' and result::text not like '%Welcome to%') from public.shared_action_events where property_id=f.property_id),'semantic decisions retain identities without raw copy or training eligibility');
end$$;
do $$declare f fixture;input jsonb;new_id uuid:=gen_random_uuid();before_count bigint;connection uuid:=gen_random_uuid();job uuid:=gen_random_uuid();action uuid:=gen_random_uuid();publication uuid:=gen_random_uuid();begin
 select * into f from fixture;
 select count(*) into before_count from public.social_content_packages where property_id=f.property_id;
 input:=jsonb_build_object('content',jsonb_set(f.content,'{variants,0,assetIds}',jsonb_build_array(gen_random_uuid())),'authorKind','user','validation','[[]]'::jsonb);
 perform pg_temp.check(public.save_forgestudio_revision(gen_random_uuid(),f.property_id,f.actor_id,input)->>'state'='asset_unavailable','unavailable revision asset is rejected before creating a package');
 perform pg_temp.check((select count(*)=before_count from public.social_content_packages where property_id=f.property_id),'rejected asset leaves no empty package');
 input:=jsonb_build_object('packageId',f.package_id,'expectedRevisionId',f.edited_id,'content',jsonb_set(f.content,'{variants}',jsonb_build_array(f.content->'variants'->0,f.content->'variants'->0)),'authorKind','user','reason','Duplicate channels fixture','validation','[[],[]]'::jsonb);
 begin perform public.save_forgestudio_revision(new_id,f.property_id,f.actor_id,input);raise exception 'FAIL duplicate variant accepted';exception when unique_violation then null;end;
 perform pg_temp.check(not exists(select 1 from public.social_content_revisions where id=new_id) and (select approval_status='approved' from public.social_content_revisions where id=f.edited_id),'variant insertion failure rolls back new revision and preserves approved predecessor');
 insert into public.social_connections(id,property_id,platform,account_id,is_active)values(connection,f.property_id,'facebook','local-fixture-account',true);
 insert into public.shared_jobs(id,org_id,property_id,domain,subject_type,lifecycle_status,lease_owner,lease_expires_at)values(job,'22222222-2222-2222-2222-222222222222',f.property_id,'forgestudio.publication','social_publication','queued','local-fixture-worker',clock_timestamp()+interval '5 minutes');
 insert into public.shared_action_attempts(id,job_id,org_id,property_id,action_type,lifecycle_status,execution_status)values(action,job,'22222222-2222-2222-2222-222222222222',f.property_id,'publish_social_content_revision','queued','approved_pending_execution');
 insert into public.social_publications(id,org_id,property_id,package_id,revision_id,variant_id,connection_id,platform,scheduled_for,status,shared_job_id,shared_action_attempt_id)select publication,'22222222-2222-2222-2222-222222222222',f.property_id,f.package_id,f.edited_id,id,connection,'facebook',clock_timestamp()+interval '1 day','scheduled',job,action from public.social_content_variants where revision_id=f.edited_id limit 1;
 input:=jsonb_build_object('packageId',f.package_id,'expectedRevisionId',f.edited_id,'content',f.content,'authorKind','user','reason','Reviewed updated explanation','validation','[[]]'::jsonb);
 perform pg_temp.check(public.save_forgestudio_revision(new_id,f.property_id,f.actor_id,input)->>'state'='publication_in_progress','claimed publication holds revision changes even before publishing status is saved');
 perform pg_temp.check((select current_revision_id=f.edited_id from public.social_content_packages where id=f.package_id),'held edit cannot move the approved package pointer');
 update public.shared_jobs set lease_owner=null,lease_expires_at=null where id=job;
 perform pg_temp.check(public.save_forgestudio_revision(new_id,f.property_id,f.actor_id,input)->>'state'='saved','unclaimed scheduled content can be revised');
 perform pg_temp.check((select status='cancelled' from public.social_publications where id=publication) and (select lifecycle_status='cancelled' from public.shared_jobs where id=job) and (select execution_status='cancelled' from public.shared_action_attempts where id=action),'revision saves cancel old publication and all queue projections together');
end$$;

select count(*) as assertions from checks;
rollback;
